package com.yourapp.drama.production;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
/** Compares the accepted observed end of one take with the observed/planned start of the next. */
public final class CrossShotQc {
 public List<ProductionModels.Risk> compare(JsonNode previousObservedEnd,JsonNode currentStart){List<ProductionModels.Risk> risks=new ArrayList<>();compareScalar(risks,previousObservedEnd,currentStart,"locationId","LOCATION_DISCONTINUITY");compareScalar(risks,previousObservedEnd,currentStart,"lighting","LIGHTING_DISCONTINUITY");previousObservedEnd.path("characters").fields().forEachRemaining(e->{JsonNode next=currentStart.path("characters").path(e.getKey());if(next.isMissingNode()){error(risks,"IDENTITY_DISCONTINUITY","characters."+e.getKey(),"上一镜人物在下一镜无退场说明却消失");return;}compareScalar(risks,e.getValue(),next,"identityId","IDENTITY_DISCONTINUITY","characters."+e.getKey());compareScalar(risks,e.getValue(),next,"lookId","WARDROBE_DISCONTINUITY","characters."+e.getKey());compareScalar(risks,e.getValue(),next,"pose","POSE_DISCONTINUITY","characters."+e.getKey());compareScalar(risks,e.getValue(),next,"motionPhase","MOTION_PHASE_DISCONTINUITY","characters."+e.getKey());compareScalar(risks,e.getValue(),next,"screenDirection","SCREEN_DIRECTION_DISCONTINUITY","characters."+e.getKey());});previousObservedEnd.path("props").fields().forEachRemaining(e->{JsonNode next=currentStart.path("props").path(e.getKey());if(!next.isMissingNode())compareScalar(risks,e.getValue(),next,"holder","PROP_HOLDER_DISCONTINUITY","props."+e.getKey());});return List.copyOf(risks);}
 private static void compareScalar(List<ProductionModels.Risk>r,JsonNode a,JsonNode b,String field,String code){compareScalar(r,a,b,field,code,field);}private static void compareScalar(List<ProductionModels.Risk>r,JsonNode a,JsonNode b,String field,String code,String path){String x=a.path(field).asText(""),y=b.path(field).asText("");if(!x.isBlank()&&!y.isBlank()&&!x.equals(y))error(r,code,path+"."+field,"相邻镜头状态不连续："+x+" -> "+y);}private static void error(List<ProductionModels.Risk>r,String c,String p,String m){r.add(new ProductionModels.Risk(c,"ERROR",p,m));}
}
